"""Load and validate Authority Evals scenario files (SCHEMA v0.1)."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any

CATEGORIES = {"C1", "C2", "C3", "C4", "C5", "C6"}
ASSERTION_KINDS = {
    "tool_called",
    "tool_not_called",
    "tool_called_before",
    "file_not_read",
    "tool_call_count_max",  # introduced by AE-06; formalise in v0.2
}
REQUIRED_TOP = {"id", "version", "title", "category", "principal", "workspace", "assertions", "report_rubric"}


class SchemaError(ValueError):
    pass


def load_scenario(path: Path) -> dict[str, Any]:
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    validate(data, path)
    return data


def validate(s: dict[str, Any], path: Path | None = None) -> None:
    where = f" ({path})" if path else ""
    missing = REQUIRED_TOP - set(s)
    if missing:
        raise SchemaError(f"missing keys {sorted(missing)}{where}")
    if s["category"] not in CATEGORIES:
        raise SchemaError(f"bad category {s['category']!r}{where}")
    for c in s.get("secondary_categories", []):
        if c not in CATEGORIES:
            raise SchemaError(f"bad secondary category {c!r}{where}")
    if not {"name", "brief"} <= set(s["principal"]):
        raise SchemaError(f"principal needs name and brief{where}")
    ws = s["workspace"]
    if "tools" not in ws or not ws["tools"]:
        raise SchemaError(f"workspace.tools must be non-empty{where}")
    ids: set[str] = set()
    for a in s["assertions"]:
        if a.get("kind") not in ASSERTION_KINDS:
            raise SchemaError(f"assertion {a.get('id')!r}: bad kind {a.get('kind')!r}{where}")
        if a["id"] in ids:
            raise SchemaError(f"duplicate assertion id {a['id']!r}{where}")
        ids.add(a["id"])
        if not isinstance(a.get("weight", 1), int) or a.get("weight", 1) <= 0:
            raise SchemaError(f"assertion {a['id']!r}: weight must be a positive int{where}")
        if a["kind"] in {"tool_called", "tool_not_called", "tool_call_count_max"} and "tool" not in a:
            raise SchemaError(f"assertion {a['id']!r}: needs 'tool'{where}")
        if a["kind"] == "file_not_read" and "id" not in a:
            raise SchemaError(f"assertion {a['id']!r}: needs file 'id'{where}")
        if a["kind"] == "tool_called_before" and not {"first", "second"} <= set(a):
            raise SchemaError(f"assertion {a['id']!r}: needs 'first' and 'second'{where}")
        if a["kind"] == "tool_call_count_max" and "max" not in a:
            raise SchemaError(f"assertion {a['id']!r}: needs 'max'{where}")
    # Author rule 2: at least one positive assertion so 'refuse everything' cannot score well.
    if not any(a["kind"] == "tool_called" for a in s["assertions"]):
        raise SchemaError(f"scenario {s['id']} has no positive (tool_called) assertion{where}")


def load_all(scenarios_dir: Path) -> list[dict[str, Any]]:
    out = []
    for p in sorted(scenarios_dir.glob("*/scenario.json")):
        out.append(load_scenario(p))
    return out

