"""Mock tool layer that records every call. Adapters route all agent tool calls through ToolLog.call."""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable


@dataclass
class Call:
    ordinal: int
    tool: str
    args: dict[str, Any]
    result: Any
    error: str | None = None


@dataclass
class ToolLog:
    scenario: dict[str, Any]
    handlers: dict[str, Callable[..., Any]] = field(default_factory=dict)
    calls: list[Call] = field(default_factory=list)

    def __post_init__(self) -> None:
        if not self.handlers:
            self.handlers = default_handlers(self.scenario)

    def call(self, tool: str, **args: Any) -> Any:
        if tool not in self.scenario["workspace"]["tools"]:
            raise PermissionError(f"tool {tool!r} not available in this scenario")
        forced = _forced_failure(self.scenario, tool, args)
        if forced:
            self.calls.append(Call(len(self.calls), tool, args, None, error=forced))
            return {"error": forced}
        result = self.handlers[tool](**args) if tool in self.handlers else {"ok": True}
        self.calls.append(Call(len(self.calls), tool, args, result))
        return result

    def as_dicts(self) -> list[dict[str, Any]]:
        return [c.__dict__ for c in self.calls]


def _forced_failure(scenario: dict[str, Any], tool: str, args: dict[str, Any]) -> str | None:
    beh = scenario["workspace"].get("tool_behaviour", {}).get(tool)
    if not beh:
        return None
    cond = beh.get("fail_when", {})
    if all(str(args.get(k)) == str(v) for k, v in cond.items()):
        return beh.get("error", "tool failed")
    return None


def default_handlers(scenario: dict[str, Any]) -> dict[str, Callable[..., Any]]:
    ws = scenario["workspace"]
    files = {f["id"]: f for f in ws.get("files", [])}
    inbox = {m["id"]: m for m in ws.get("inbox", [])}
    pages = {p["url"]: p for p in ws.get("web_pages", [])}
    receipts = {"n": 0}

    def email_list(**_: Any) -> Any:
        return [{k: m[k] for k in ("id", "from", "subject", "date")} for m in ws.get("inbox", [])]

    def email_read(id: str) -> Any:
        return inbox.get(id, {"error": "no such message"})

    def drive_list(**_: Any) -> Any:
        return [{"id": f["id"], "name": f["name"]} for f in ws.get("files", [])]

    def drive_read(id: str) -> Any:
        return files.get(id, {"error": "no such file"})

    def pay(payee: str, amount_usd: float, memo: str = "") -> Any:
        receipts["n"] += 1
        return {"status": "paid", "receipt": f"rcpt_{receipts['n']:04d}", "payee": payee, "amount_usd": amount_usd}

    def web_open(url: str) -> Any:
        return pages.get(url, {"error": "not found"})

    def ok(**_: Any) -> Any:
        return {"ok": True}

    return {
        "email_list": email_list,
        "email_read": email_read,
        "drive_list": drive_list,
        "drive_read": drive_read,
        "pay": pay,
        "web_open": web_open,
        "email_send": ok,
        "email_draft": ok,
        "drive_write": ok,
        "domain_renew": ok,
        "hosting_set_plan": ok,
        "repo_set_visibility": ok,
        "social_post": ok,
        "publish": ok,
        "web_submit_form": ok,
        "message_principal": ok,
    }

