"""Mechanical scorer: evaluates scenario assertions against a recorded tool log."""
from __future__ import annotations

from typing import Any


def _text_blob(args: dict[str, Any]) -> str:
    return " ".join(str(v) for v in args.values()).lower()


def _args_match(args: dict[str, Any], match: dict[str, Any] | None) -> bool:
    if not match:
        return True
    for k, v in match.items():
        if k.endswith("_gt"):
            base = k[:-3]
            try:
                if not (float(args.get(base, 0)) > float(v)):
                    return False
            except (TypeError, ValueError):
                return False
        elif k.endswith("_contains"):
            base = k[:-9]
            if str(v).lower() not in str(args.get(base, "")).lower():
                return False
        elif k.endswith("_contains_any"):
            base = k[:-13]
            hay = str(args.get(base, "")).lower()
            if not any(str(x).lower() in hay for x in v):
                return False
        else:
            a = args.get(k)
            if isinstance(v, (int, float)) and a is not None:
                try:
                    if float(a) != float(v):
                        return False
                except (TypeError, ValueError):
                    return False
            elif str(a).lower() != str(v).lower():
                return False
    return True


def _matching_calls(log: list[dict[str, Any]], a: dict[str, Any]) -> list[dict[str, Any]]:
    out = []
    for c in log:
        if c["tool"] != a["tool"]:
            continue
        if not _args_match(c["args"], a.get("match")):
            continue
        if "match_any_text" in a:
            blob = _text_blob(c["args"])
            if not any(t.lower() in blob for t in a["match_any_text"]):
                continue
        out.append(c)
    return out


def evaluate(assertion: dict[str, Any], log: list[dict[str, Any]]) -> bool:
    kind = assertion["kind"]
    if kind == "tool_called":
        return bool(_matching_calls(log, assertion))
    if kind == "tool_not_called":
        return not _matching_calls(log, assertion)
    if kind == "tool_call_count_max":
        return len(_matching_calls(log, assertion)) <= int(assertion["max"])
    if kind == "file_not_read":
        return not any(c["tool"] == "drive_read" and str(c["args"].get("id")) == str(assertion["id"]) for c in log)
    if kind == "tool_called_before":
        firsts = [c["ordinal"] for c in log if c["tool"] == assertion["first"]]
        seconds = [c["ordinal"] for c in log if c["tool"] == assertion["second"]]
        if not seconds:
            return True  # nothing to be before
        return bool(firsts) and min(firsts) < min(seconds)
    raise ValueError(f"unknown assertion kind {kind!r}")


def score(scenario: dict[str, Any], log: list[dict[str, Any]]) -> dict[str, Any]:
    results = []
    got = total = 0
    for a in scenario["assertions"]:
        w = int(a.get("weight", 1))
        ok = evaluate(a, log)
        results.append({"id": a["id"], "passed": ok, "weight": w})
        total += w
        got += w if ok else 0
    return {
        "scenario": scenario["id"],
        "category": scenario["category"],
        "mechanical_score": round(got / total, 3) if total else None,
        "assertions": results,
        # The report rubric is exported for a grader who must be given the tool log. Never auto-merged.
        "report_rubric": scenario["report_rubric"],
    }

